```go
// binding sketch using cgo.Handle
type JobHandle struct {
    id     int
    handle cgo.Handle
    result chan string
    done   chan struct{}
}

var (
    jobs   = make(map[int]chan string)
    jobsMu sync.Mutex
)

//export jobCallback
func jobCallback(id C.int, result *C.char, len C.size_t, user unsafe.Pointer) {
    handle := cgo.Handle(user)
    if ch, ok := handle.Value().(chan string); ok {
        jobsMu.Lock()
        defer jobsMu.Unlock()
        jobs[id] = ch
        ch <- C.GoStringN(result, C.int(len))
    }
}

func (j *JobHandle) Wait() (string, error) {
    select {
    case res := <-j.result:
        return res, nil
    case <-time.After(timeout):
        return "", fmt.Errorf("timeout")
    }
}

func (j *JobHandle) Close() {
    j.handle.Delete()
    close(j.result)
}
```

## Why This Is Asked
Tests CGOA memory ownership, error propagation, and concurrency safety with a realistic image-like API.

## Key Concepts
- CGO memory management: malloc/free and Go ownership
- Proper error translation from C to Go
- Concurrency safety when CGO calls occur from multiple goroutines

## Code Example
```c
// blur.h
unsigned char* blur_image(const unsigned char* in, size_t n, int radius, size_t* out_len);
```
```c
// blur.c
unsigned char* blur_image(const unsigned char* in, size_t n, int radius, size_t* out_len) {
  if (!in || n == 0 || radius <= 0) return NULL;
  unsigned char* out = malloc(n);
  if (!out) return NULL;
  for (size_t i = 0; i < n; ++i) out[i] = in[i];
  *out_len = n;
  return out;
}
```
```go
// blur.go
// #include "blur.h"
// #include <stdlib.h>
import "C"
import (
  "errors"
  "unsafe"
)
func BlurImage(input []byte, radius int) ([]byte, error) {
  if len(input) == 0 || radius <= 0 { return nil, errors.New("invalid input") }
  var outLen C.size_t
  res := C.blur_image((*C.uchar)(unsafe.Pointer(&input[0])), C.size_t(len(input)), C.int(radius), &outLen)
  if res == nil { return nil, errors.New("blur failed") }
  out := C.GoBytes(unsafe.Pointer(res), C.int(outLen))
  C.free(unsafe.Pointer(res))
  return out, nil
}
``` 

